# Write your MySQL query statement below
SELECT session_id, user_id, c1 AS session_duration_minutes, c2 AS scroll_count FROM (SELECT session_id, user_id, TIMESTAMPDIFF(MINUTE, MIN(event_timestamp), MAX(event_timestamp)) AS c1, SUM(CASE WHEN event_type = 'scroll' THEN 1 ELSE 0 END) AS c2, (SUM(CASE WHEN event_type = 'click' THEN 1 ELSE 0 END) / SUM(CASE WHEN event_type = 'scroll' THEN 1 ELSE 0 END)) AS c3, SUM(CASE WHEN event_type = 'purchase' THEN 1 ELSE 0 END) AS c4 FROM app_events GROUP BY session_id, user_id HAVING c1 > 30 AND c2 >= 5 AND c3 < 0.2 AND c4 = 0) T ORDER BY scroll_count DESC, session_id;